// Native Unity meshes, materials and articulated prefabs. No sprite billboards.
public static class Final3DBuilder {
 const string Root="Assets/Resources/Final3D";
 static readonly Dictionary<string,Mesh> meshes=new Dictionary<string,Mesh>();
 static readonly Dictionary<string,Material> mats=new Dictionary<string,Material>();
 static int models;
 [MenuItem(NoiteSemFim.GameIdentity.Title + "/3D/Gerar todos os assets")]
 public static void BuildAll(){Directory.CreateDirectory(Root+"/Meshes");Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory("Modelos3D-OBJ");meshes.Clear();mats.Clear();models=0;
  Mat("stone",new Color(.72f,.78f,.85f));Mat("stone2",new Color(.57f,.64f,.72f));Mat("dark",new Color(.055f,.065f,.10f));Mat("blue",new Color(.12f,.19f,.40f));Mat("teal",new Color(.06f,.31f,.32f));Mat("green",new Color(.08f,.32f,.19f));Mat("violet",new Color(.28f,.10f,.43f));Mat("red",new Color(.42f,.07f,.05f));Mat("gold",new Color(.8f,.58f,.24f),0,.65f);Mat("silver",new Color(.60f,.73f,.80f),0,.6f);Mat("skin",new Color(.90f,.64f,.44f));Mat("hair",new Color(.065f,.045f,.08f));Mat("white",new Color(.83f,.86f,.90f));Mat("bone",new Color(.72f,.67f,.48f));Mat("eye",new Color(.01f,.02f,.045f));Mat("arcane",new Color(.05f,.55f,1),1.6f);Mat("ice",new Color(.2f,.85f,1),1);Mat("lava",new Color(1,.19f,.025f),1.5f);Mat("void",new Color(.66f,.15f,1),1.4f);Mat("moon",new Color(.70f,.82f,1),1.5f);Mat("water",new Color(.04f,.31f,.43f),.15f);Mat("frost",new Color(.35f,.67f,.79f),.25f);Mat("grass",new Color(.38f,.31f,.09f));
  MeshAsset("box",Box());MeshAsset("ball",Lathe(new[]{new Vector2(0,-.5f),new Vector2(.35f,-.35f),new Vector2(.5f,0),new Vector2(.35f,.35f),new Vector2(0,.5f)},8));MeshAsset("tube",Lathe(new[]{new Vector2(0,-.5f),new Vector2(.5f,-.5f),new Vector2(.5f,.5f),new Vector2(0,.5f)},10));MeshAsset("cone",Lathe(new[]{new Vector2(0,-.5f),new Vector2(.5f,-.5f),new Vector2(0,.5f)},8));MeshAsset("skirt",Lathe(new[]{new Vector2(0,-.5f),new Vector2(.5f,-.5f),new Vector2(.24f,.5f),new Vector2(0,.5f)},10));MeshAsset("crystal",Lathe(new[]{new Vector2(0,-.5f),new Vector2(.5f,0),new Vector2(0,.5f)},5));MeshAsset("ring",Ring());MeshAsset("ringThin",Ring(.002f));MeshAsset("wing",Wing());
  for(int h=0;h<3;h++)for(int a=0;a<5;a++)Save("hero-"+h+"-"+a,Hero(h,a));
  for(int i=0;i<3;i++)Save("dragon-"+i,Dragon(i));
  for(int i=0;i<8;i++)Save("enemy-"+i,Enemy(i));
  for(int i=0;i<8;i++)Save("ability-"+i,Ability(i));
  for(int i=0;i<8;i++)Save("relic-"+i,Relic(i));
  for(int i=0;i<4;i++)Save("loot-"+i,Loot(i));
  for(int i=0;i<6;i++)Save("status-"+i,Status(i));
  for(int i=0;i<4;i++)Save("ground-"+i,Ground(i));
  for(int i=0;i<12;i++)Save("prop-"+i,Prop(i));
  Save("arena",Arena());
  File.WriteAllText(Root+"/manifest.json","{\"version\":\"0.14\",\"revision\":3,\"prefabs\":"+models+",\"heroes\":15,\"dragons\":3,\"enemiesAndBosses\":8,\"abilities\":8,\"relics\":8,\"loot\":4,\"status\":6,\"ground\":4,\"props\":12,\"arena\":1,\"format\":\"Unity Mesh + Material + Prefab; OBJ/MTL exports\"}");
  AssetDatabase.SaveAssets();AssetDatabase.Refresh();Debug.Log("FINAL 3D ASSETS: "+models+" articulated prefabs, 9 meshes, 23 materials, OBJ/MTL exports.");
 }
 public static void EnsureAssets(){if(!File.Exists(Root+"/manifest.json")||!File.ReadAllText(Root+"/manifest.json").Contains("\"revision\":3"))BuildAll();}
 static void Mat(string key,Color color,float glow=0,float metal=0){var m=new Material(Shader.Find("Standard")){name=key,color=color};m.enableInstancing=true;if(key=="stone"||key=="stone2")m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Textures/floor-albedo-v14.png");if(key=="blue"||key=="teal"||key=="green"||key=="violet"||key=="red")m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Textures/cloth-albedo-v14.png");m.SetFloat("_Metallic",metal);m.SetFloat("_Glossiness",.28f);if(glow>0){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",color*glow);}string path=Root+"/Materials/"+key+".mat";var existing=AssetDatabase.LoadAssetAtPath<Material>(path);if(existing!=null){EditorUtility.CopySerialized(m,existing);UnityEngine.Object.DestroyImmediate(m);m=existing;}else AssetDatabase.CreateAsset(m,path);mats[key]=m;}
 static void MeshAsset(string key,Mesh mesh){mesh.name=key;string path=Root+"/Meshes/"+key+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing!=null){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,path);meshes[key]=mesh;}
 static GameObject New(string name)=>new GameObject(name);
 static Transform Pivot(Transform parent,string name,Vector3 pos){var t=New(name).transform;t.SetParent(parent,false);t.localPosition=pos;return t;}
 static Transform Part(Transform parent,string name,string shape,string material,Vector3 p,Vector3 scale,Vector3 rotation=default){var t=Pivot(parent,name,p);t.localScale=scale;t.localRotation=Quaternion.Euler(rotation);t.gameObject.AddComponent<MeshFilter>().sharedMesh=meshes[shape];var r=t.gameObject.AddComponent<MeshRenderer>();r.sharedMaterial=mats[material];r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;return t;}
 static void Save(string name,GameObject go){go.name=name;if(name.StartsWith("ability-")||name.StartsWith("ground-")||name.StartsWith("status-"))foreach(var renderer in go.GetComponentsInChildren<MeshRenderer>()){renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;}PrefabUtility.SaveAsPrefabAsset(go,Root+"/"+name+".prefab");Export(go,name);UnityEngine.Object.DestroyImmediate(go);models++;}
 static string ArmorCloth(int hero,int armor)=>armor==0?(hero==0?"blue":hero==1?"teal":"white"):armor==1?"green":armor==2?"blue":armor==3?"red":"violet";
 static string ArmorMetal(int armor)=>armor==2?"silver":armor==3?"dark":armor==1?"stone":"gold";
 static string ArmorGem(int armor)=>armor==1?"teal":armor==2?"ice":armor==3?"lava":armor==4?"void":"arcane";
 static GameObject Hero(int id,int armor){var go=New("Hero");var r=go.transform;string cloth=ArmorCloth(id,armor),metal=ArmorMetal(armor),gem=ArmorGem(armor);
  Part(r,"Cape","skirt",cloth,new Vector3(0,1.01f,-.22f),new Vector3(.90f,1.04f,.32f),new Vector3(-9,0,0));Part(r,"Torso","tube",cloth,new Vector3(0,1.06f,0),new Vector3(.60f,.59f,.40f));Part(r,"Belt","tube","gold",new Vector3(0,.82f,0),new Vector3(.64f,.09f,.44f));Part(r,"ChestGem","crystal",gem,new Vector3(0,1.21f,.225f),new Vector3(.17f,.24f,.08f));
  if(id!=1)Part(r,"Skirt","skirt",cloth,new Vector3(0,.66f,0),new Vector3(.85f,.45f,.68f));
  for(int side=-1;side<=1;side+=2){string suffix=side<0?"L":"R";var leg=Pivot(r,"Leg"+suffix,new Vector3(side*.16f,.72f,0));Part(leg,"LegMesh","box",metal,new Vector3(0,-.22f,0),new Vector3(.21f,.42f,.23f));Part(leg,"KneePlate","crystal","gold",new Vector3(0,-.22f,.13f),new Vector3(.14f,.23f,.05f));Part(leg,"BootCuff","tube",metal,new Vector3(0,-.44f,0),new Vector3(.27f,.09f,.29f));Part(leg,"Boot","box","dark",new Vector3(0,-.55f,.07f),new Vector3(.27f,.21f,.39f));var arm=Pivot(r,"Arm"+suffix,new Vector3(side*.43f,1.30f,0));Part(arm,"Shoulder","ball",metal,Vector3.zero,new Vector3(.30f,.28f,.33f));Part(arm,"ArmMesh","box",cloth,new Vector3(0,-.24f,0),new Vector3(.18f,.42f,.20f));Part(arm,"Hand","ball","skin",new Vector3(0,-.48f,0),Vector3.one*.20f);
   if(armor>0){Part(arm,"Edge","ring","gold",Vector3.zero,Vector3.one*.28f);if(armor==2||armor==3)Part(arm,"ShoulderCrystal","crystal",gem,new Vector3(side*.08f,.22f,0),new Vector3(.16f,.39f,.16f),new Vector3(0,0,-side*23));}
   if(id==1){Part(arm,"Blade","crystal","silver",new Vector3(0,-.73f,.06f),new Vector3(.16f,.60f,.06f));Part(arm,"Guard","box","gold",new Vector3(0,-.46f,.06f),new Vector3(.29f,.06f,.10f));}
   if(side==1&&id==0){Part(arm,"Staff","tube","gold",new Vector3(.1f,-.12f,.10f),new Vector3(.06f,1.50f,.06f));Part(arm,"StaffOrb","ball","arcane",new Vector3(.1f,.69f,.10f),Vector3.one*.26f);Part(arm,"StaffCrown","ring","gold",new Vector3(.1f,.69f,.10f),Vector3.one*.39f,new Vector3(90,0,0));}
   if(side==1&&id==2){Part(arm,"SolarOrb","ball","gold",new Vector3(0,-.29f,.29f),Vector3.one*.38f);Part(arm,"SolarCore","ball","moon",new Vector3(0,-.29f,.34f),Vector3.one*.27f);}
  }
  var head=Pivot(r,"Head",new Vector3(0,1.66f,0));Part(head,"Hair","ball",id==0?"hair":"white",new Vector3(0,.06f,-.08f),new Vector3(.56f,.58f,.49f));Part(head,"Face","ball","skin",new Vector3(0,-.02f,.055f),new Vector3(.44f,.44f,.38f));for(int side=-1;side<=1;side+=2){Part(head,"Eye","ball","eye",new Vector3(side*.105f,.01f,.229f),new Vector3(.068f,.10f,.035f));Part(head,"EyeGlint","ball","arcane",new Vector3(side*.105f,.03f,.249f),new Vector3(.021f,.025f,.012f));}
  Part(head,"Nose","ball","skin",new Vector3(0,-.045f,.25f),new Vector3(.055f,.06f,.045f));Part(head,"Mouth","box","hair",new Vector3(0,-.14f,.223f),new Vector3(.08f,.018f,.015f));for(int sgn=-1;sgn<=1;sgn+=2){Part(head,"HairLock","cone",id==0?"hair":"white",new Vector3(sgn*.22f,.02f,.13f),new Vector3(.16f,.40f,.15f),new Vector3(0,0,sgn*15));Part(r,"ChestTrim","box","gold",new Vector3(sgn*.19f,1.09f,.207f),new Vector3(.035f,.44f,.035f),new Vector3(0,0,sgn*12));}if(id==0){Part(head,"LongHair","box","hair",new Vector3(0,-.24f,-.15f),new Vector3(.52f,.55f,.18f));Part(head,"HatBrim","tube","blue",new Vector3(0,.29f,0),new Vector3(.99f,.065f,.86f));Part(head,"Hat","cone",cloth,new Vector3(-.08f,.65f,0),new Vector3(.57f,.74f,.55f),new Vector3(0,0,14));Part(head,"HatBand","tube","gold",new Vector3(0,.34f,0),new Vector3(.57f,.08f,.55f));}
  else if(id==1){for(int k=0;k<7;k++){float a=k*6.283f/7;Part(head,"HairSpike","cone","white",new Vector3(Mathf.Sin(a)*.18f,.23f,Mathf.Cos(a)*.17f),new Vector3(.21f,.26f,.20f),new Vector3(Mathf.Cos(a)*25,0,-Mathf.Sin(a)*25));}}
  else {Part(head,"Crown","ring","gold",new Vector3(0,.28f,0),new Vector3(.61f,.20f,.56f));for(int side=-1;side<=1;side+=2)Part(head,"CrownHorn","cone","gold",new Vector3(side*.25f,.45f,0),new Vector3(.14f,.40f,.13f),new Vector3(0,0,-side*24));Part(head,"CrownGem","crystal",gem,new Vector3(0,.31f,.28f),new Vector3(.15f,.21f,.08f));}
  return go;
 }
 static GameObject Dragon(int id){var go=New("Dragon");var r=go.transform;string body=id==0?"red":id==1?"blue":"violet",gem=id==0?"lava":id==1?"ice":"gold";Part(r,"Body","ball",body,new Vector3(0,.55f,0),new Vector3(.48f,.58f,.73f));Part(r,"Belly","ball",gem,new Vector3(0,.51f,.16f),new Vector3(.32f,.42f,.43f));Part(r,"Head","ball",body,new Vector3(0,.89f,.30f),new Vector3(.48f,.40f,.47f));Part(r,"Muzzle","ball",gem,new Vector3(0,.83f,.57f),new Vector3(.34f,.21f,.27f));
  for(int side=-1;side<=1;side+=2){Part(r,"Eye","ball","eye",new Vector3(side*.20f,.95f,.43f),Vector3.one*.085f);Part(r,"Horn","cone","gold",new Vector3(side*.17f,1.16f,.18f),new Vector3(.10f,.34f,.10f),new Vector3(-20,0,-side*22));var wing=Pivot(r,side<0?"WingL":"WingR",new Vector3(side*.20f,.71f,-.07f));Part(wing,"Membrane","wing",body,Vector3.zero,new Vector3(side*.77f,.70f,1));Part(wing,"WingBone","box","gold",new Vector3(side*.32f,.13f,0),new Vector3(.76f,.04f,.045f),new Vector3(0,0,side*22));Part(r,"Foot","ball",body,new Vector3(side*.18f,.23f,.23f),new Vector3(.21f,.23f,.33f));}
  var tail=Pivot(r,"Tail",new Vector3(0,.53f,-.33f));Part(tail,"TailMesh","cone",body,new Vector3(0,-.03f,-.34f),new Vector3(.24f,.83f,.22f),new Vector3(-100,0,0));Part(tail,"Tip","crystal",gem,new Vector3(0,-.09f,-.72f),new Vector3(.21f,.28f,.18f));return go;}
 static GameObject Enemy(int id){if(id==1){var bat=New("Bat");Part(bat.transform,"Body","ball","violet",new Vector3(0,.9f,0),new Vector3(.38f,.49f,.37f));Part(bat.transform,"Head","ball","dark",new Vector3(0,1.15f,.10f),Vector3.one*.33f);for(int side=-1;side<=1;side+=2){Part(bat.transform,"Eye","ball","lava",new Vector3(side*.09f,1.18f,.27f),Vector3.one*.07f);var wing=Pivot(bat.transform,side<0?"WingL":"WingR",new Vector3(side*.16f,1,0));Part(wing,"Wing","wing","violet",Vector3.zero,new Vector3(side*1.1f,.8f,1));}return bat;}
  int armor=id==6?2:id==7?3:id==4?4:1;var go=Hero(id==5?0:1,armor);go.name="Enemy";var head=go.transform.Find("Head");if(head!=null)UnityEngine.Object.DestroyImmediate(head.gameObject);string material=id==0?"bone":id==2?"stone":id==6?"silver":id==7?"dark":"dark";string glow=id==6?"ice":id==7?"lava":id==3?"teal":"void";
  Part(go.transform,"MonsterHead","ball",material,new Vector3(0,1.70f,0),new Vector3(.52f,.56f,.47f));for(int side=-1;side<=1;side+=2)Part(go.transform,"Eye","ball",id==0?"eye":glow,new Vector3(side*.13f,1.75f,.22f),new Vector3(.09f,.08f,.05f));
  if(id==0){foreach(var m in go.GetComponentsInChildren<MeshRenderer>())if(m.name!="Eye")m.sharedMaterial=mats["bone"];Part(go.transform,"Jaw","box","bone",new Vector3(0,1.50f,.13f),new Vector3(.32f,.10f,.26f));}
  if(id==2){Part(go.transform,"BoulderTorso","ball","stone",new Vector3(0,1.0f,0),new Vector3(.95f,1.1f,.63f));}
  if(id==5)Part(go.transform,"Hood","cone","dark",new Vector3(0,2.0f,-.02f),new Vector3(.70f,.75f,.65f));
  if(id==3||id==4||id==6||id==7){for(int side=-1;side<=1;side+=2){Part(go.transform,"Horn","cone",id==6?"ice":"gold",new Vector3(side*.28f,2.1f,0),new Vector3(.16f,.70f,.16f),new Vector3(0,0,-side*20));Part(go.transform,"ShoulderSpike","crystal",glow,new Vector3(side*.53f,1.58f,0),new Vector3(.20f,.64f,.22f),new Vector3(0,0,-side*25));}Part(go.transform,"Crown","ring","gold",new Vector3(0,1.94f,0),Vector3.one*.71f);Part(go.transform,"Heart","crystal",glow,new Vector3(0,1.18f,.29f),new Vector3(.24f,.38f,.14f));}
  if(id==4){Part(go.transform,"EclipseHalo","ring","void",new Vector3(0,1.65f,-.29f),Vector3.one*1.45f,new Vector3(68,0,0));Part(go.transform,"OuterHalo","ring","gold",new Vector3(0,1.65f,-.31f),Vector3.one*1.70f,new Vector3(68,0,0));}
  return go;
 }
 static GameObject Relic(int id){var go=New("Relic");var r=go.transform;int armor=id/2+1;string metal=ArmorMetal(armor),gem=ArmorGem(armor);if(id%2==0){Part(r,"Breastplate","tube",metal,new Vector3(0,.40f,0),new Vector3(.74f,.74f,.40f));for(int s=-1;s<=1;s+=2)Part(r,"Shoulder","ball",metal,new Vector3(s*.44f,.65f,0),new Vector3(.36f,.31f,.40f));Part(r,"Gem","crystal",gem,new Vector3(0,.52f,.23f),new Vector3(.23f,.33f,.12f));Part(r,"Belt","tube","gold",new Vector3(0,.08f,0),new Vector3(.76f,.09f,.43f));}else{Part(r,"Pendant","ring","gold",new Vector3(0,.41f,0),Vector3.one*.59f,new Vector3(90,0,0));Part(r,"Gem","crystal",gem,new Vector3(0,.36f,.03f),new Vector3(.34f,.53f,.17f));Part(r,"Clasp","tube","gold",new Vector3(0,.78f,0),new Vector3(.18f,.17f,.13f));}return go;}
 static GameObject Ability(int id){var go=New("Ability");var r=go.transform;string color=id==0?"arcane":id==1?"silver":id==2?"gold":id==3?"ice":id==4?"void":id==5?"lava":id==6?"moon":"teal";
  if(id==1){Part(r,"Blade","crystal","silver",new Vector3(0,.1f,0),new Vector3(.18f,.10f,1));Part(r,"Hilt","box","gold",new Vector3(0,.1f,-.34f),new Vector3(.36f,.12f,.10f));}
  else if(id==3||id==7){Part(r,"Pulse","ring",color,Vector3.zero,Vector3.one);if(id==3)for(int i=0;i<8;i++){float a=i*Mathf.PI/4;Part(r,"IceShard","crystal",color,new Vector3(Mathf.Sin(a)*.45f,.12f,Mathf.Cos(a)*.45f),new Vector3(.08f,.28f,.08f));}}
  else if(id==4){Part(r,"Lightning","crystal",color,new Vector3(0,1.6f,0),new Vector3(.17f,3.2f,.17f));Part(r,"Impact","ring",color,Vector3.zero,Vector3.one*.7f);}
  else {Part(r,"Core","ball",color,new Vector3(0,.12f,0),Vector3.one*.72f);Part(r,"Trail","cone",color,new Vector3(0,.10f,-.44f),new Vector3(.32f,.83f,.32f),new Vector3(-90,0,0));}
  return go;}
 static GameObject Loot(int id){var go=New("Loot");if(id==1){Part(go.transform,"Chest","box","gold",new Vector3(0,.27f,0),new Vector3(.76f,.48f,.52f));Part(go.transform,"Lid","tube","dark",new Vector3(0,.53f,0),new Vector3(.78f,.53f,.45f),new Vector3(0,0,90));Part(go.transform,"Lock","box","gold",new Vector3(0,.35f,.28f),Vector3.one*.15f);}else if(id==0)Part(go.transform,"XpCrystal","crystal","arcane",new Vector3(0,.3f,0),new Vector3(.25f,.58f,.25f));else if(id==2){Part(go.transform,"Bottle","ball","red",new Vector3(0,.24f,0),new Vector3(.35f,.42f,.35f));Part(go.transform,"Cork","tube","gold",new Vector3(0,.5f,0),new Vector3(.13f,.17f,.13f));}else Part(go.transform,"Magnet","ring","gold",new Vector3(0,.25f,0),Vector3.one*.6f,new Vector3(90,0,0));return go;}
 static GameObject Status(int id){var go=New("Status");string color=id<2?"lava":id==2?"ice":id==3?"void":id==4?"white":"arcane";for(int i=0;i<5;i++){float a=i*6.283f/5;Part(go.transform,"Shard","crystal",color,new Vector3(Mathf.Sin(a)*.30f,.4f,Mathf.Cos(a)*.30f),new Vector3(.12f,.65f,.12f),new Vector3(Mathf.Cos(a)*-20,0,Mathf.Sin(a)*20));}return go;}
 static GameObject Ground(int id){var go=New("Ground");string color=id==0?"lava":id==1?"frost":id==2?"water":"white";Part(go.transform,"Pool","tube",color,new Vector3(0,.02f,0),new Vector3(1,.025f,1));if(id==0||id==1)for(int i=0;i<6;i++){float a=i*6.283f/6;Part(go.transform,"Crystal","cone",id==0?"lava":"ice",new Vector3(Mathf.Sin(a)*.32f,.12f,Mathf.Cos(a)*.32f),new Vector3(.10f,.27f,.10f));}return go;}
