  if(id==0||id==1){Part(r,"Base","box","stone",new Vector3(0,.18f,0),new Vector3(1.4f,.36f,1.4f));Part(r,"Column","tube","stone",new Vector3(0,id==0?1.8f:.95f,0),new Vector3(.64f,id==0?3.1f:1.4f,.64f));Part(r,"Cap","box","gold",new Vector3(0,id==0?3.4f:1.66f,0),new Vector3(.9f,.20f,.9f));}
