 static GameObject Arena(){var go=New("Arena do Eclipse");var r=go.transform;Part(r,"Foundation","tube","dark",new Vector3(0,-.6f,0),new Vector3(49,1.2f,49));Part(r,"Floor","tube","dark",new Vector3(0,-.12f,0),new Vector3(46,.24f,46));
