 static Mesh Box(){var v=new List<Vector3>();var t=new List<int>();Vector3[] n={Vector3.forward,Vector3.back,Vector3.left,Vector3.right,Vector3.up,Vector3.down};foreach(var normal in n){Vector3 up=Mathf.Abs(normal.y)>.9f?Vector3.forward:Vector3.up;Vector3 right=Vector3.Cross(up,normal);int k=v.Count;v.Add((normal-right-up)*.5f);v.Add((normal+right-up)*.5f);v.Add((normal+right+up)*.5f);v.Add((normal-right+up)*.5f);t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}return Mesh(v,t);}
 static Mesh Lathe(Vector2[] rings,int sides){var v=new List<Vector3>();var t=new List<int>();for(int j=0;j<rings.Length-1;j++)for(int i=0;i<sides;i++){float a=i*Mathf.PI*2/sides,b=(i+1)*Mathf.PI*2/sides;int k=v.Count;v.Add(new Vector3(Mathf.Sin(a)*rings[j].x,rings[j].y,Mathf.Cos(a)*rings[j].x));v.Add(new Vector3(Mathf.Sin(b)*rings[j].x,rings[j].y,Mathf.Cos(b)*rings[j].x));v.Add(new Vector3(Mathf.Sin(b)*rings[j+1].x,rings[j+1].y,Mathf.Cos(b)*rings[j+1].x));v.Add(new Vector3(Mathf.Sin(a)*rings[j+1].x,rings[j+1].y,Mathf.Cos(a)*rings[j+1].x));t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}return Mesh(v,t);}
 static Mesh Ring(float width=.025f){var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<32;i++)for(int j=0;j<4;j++){float a=i*Mathf.PI*2/32,b=(i+1)*Mathf.PI*2/32,c=j*Mathf.PI*.5f,d=(j+1)*Mathf.PI*.5f;int k=v.Count;foreach(var q in new[]{new Vector2(a,c),new Vector2(b,c),new Vector2(b,d),new Vector2(a,d)})v.Add(new Vector3(Mathf.Sin(q.x)*(.5f+width*Mathf.Cos(q.y)),width*Mathf.Sin(q.y),Mathf.Cos(q.x)*(.5f+width*Mathf.Cos(q.y))));t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}return Mesh(v,t);}
 static Mesh Wing(){var v=new List<Vector3>{Vector3.zero,new Vector3(1,.45f,0),new Vector3(.85f,-.28f,.07f),new Vector3(.55f,-.13f,.12f),new Vector3(.3f,-.36f,.08f),new Vector3(.14f,-.12f,0)};var t=new List<int>();int count=v.Count;v.AddRange(v.ToArray());for(int i=1;i<5;i++){t.AddRange(new[]{0,i,i+1,count,count+i+1,count+i});}return Mesh(v,t);}
 static Mesh Mesh(List<Vector3> v,List<int> t){var m=new Mesh();m.SetVertices(v);m.SetTriangles(t,0);var uv=new List<Vector2>();for(int i=0;i<v.Count;i++)uv.Add(new Vector2(i%4==1||i%4==2?1:0,i%4>=2?1:0));m.SetUVs(0,uv);m.RecalculateNormals();m.RecalculateBounds();return m;}
 static string F(float x)=>x.ToString("0.######",CultureInfo.InvariantCulture);
 static void Export(GameObject go,string name){var obj=new StringBuilder("# Noite Sem Fim 0.14 - native 3D model\nmtllib "+name+".mtl\n");var materials=new HashSet<Material>();int offset=1;foreach(var f in go.GetComponentsInChildren<MeshFilter>()){var m=f.sharedMesh;var material=f.GetComponent<MeshRenderer>().sharedMaterial;materials.Add(material);obj.AppendLine("g "+f.name);obj.AppendLine("usemtl "+material.name);foreach(var vertex in m.vertices){var p=f.transform.TransformPoint(vertex);obj.AppendLine("v "+F(p.x)+" "+F(p.y)+" "+F(p.z));}foreach(var uv in m.uv)obj.AppendLine("vt "+F(uv.x)+" "+F(uv.y));var tri=m.triangles;for(int i=0;i<tri.Length;i+=3)obj.AppendLine("f "+(tri[i]+offset)+"/"+(tri[i]+offset)+" "+(tri[i+1]+offset)+"/"+(tri[i+1]+offset)+" "+(tri[i+2]+offset)+"/"+(tri[i+2]+offset));offset+=m.vertexCount;}var mtl=new StringBuilder();foreach(var m in materials){var c=m.color;mtl.AppendLine("newmtl "+m.name+"\nKd "+F(c.r)+" "+F(c.g)+" "+F(c.b)+"\nKa 0.2 0.2 0.2\nNs 24\n");if(m.mainTexture!=null){string file=Path.GetFileName(AssetDatabase.GetAssetPath(m.mainTexture));mtl.AppendLine("map_Kd Textures/"+file);Directory.CreateDirectory("Modelos3D-OBJ/Textures");File.Copy(AssetDatabase.GetAssetPath(m.mainTexture),"Modelos3D-OBJ/Textures/"+file,true);}}File.WriteAllText("Modelos3D-OBJ/"+name+".obj",obj.ToString());File.WriteAllText("Modelos3D-OBJ/"+name+".mtl",mtl.ToString());}
